 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

import React from 'react';
import loadable from '@loadable/component';
import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';

// Components
import { Skeleton } from '@salesforce/retail-react-app/app/components/shared/ui';
import { configureRoutes } from '@salesforce/retail-react-app/app/utils/routes-utils';
import { routes as _routes } from '@salesforce/retail-react-app/app/routes';

const fallback = <Skeleton height="75vh" width="100%" />;

// Create your pages here and add them to the routes array
// Use loadable to split code into smaller js chunks
const Home = loadable(() => import('./pages/home'), { fallback });
const MyNewRoute = loadable(() => import('./pages/my-new-route'));
const Experience = loadable(() => import('./pages/experience'), { fallback });

const routes = [
  {
    path: '/',
    component: Home,
    exact: true,
  },
  {
    path: '/my-new-route',
    component: MyNewRoute,
  },
  ..._routes,
  // Contentful Studio/Experience pages — fallback after all SFCC routes.
  // `configureRoutes` strips PWA Kit's '*' catch-all so this is safely reached only for paths no other route matched.
  {
    path: '/:slug',
    component: Experience,
  },
];

export default () => {
  const config = getConfig();
  return configureRoutes(routes, config, {
    ignoredRoutes: ['/callback', '*'],
  });
};

/*
 * Copyright (c) 2023, Salesforce, Inc.
