 */

// Zimmermann storefronts — 7 SFCC sites across 6 regions.
// Site IDs sourced from bkzk-002 BM (2026-06-13). See .docs/prd/regional.md for routing rules.
//
// EU domestic is split into 4 single-locale PWA sites (one per URL prefix) because PWA Kit maps
// one site alias → one URL prefix. All 4 share sfccSiteId: 'ZimmermannEU' so every API call
// still targets the single SFCC EU site. _app-config reads sfccSiteId when present.
module.exports = [
  // AU — root (no prefix), x-default hreflang, gated to AU/Oceania IPs
  {
    id: 'ZimmermannAU',
    l10n: {
      supportedCurrencies: ['AUD'],
      defaultCurrency: 'AUD',
      defaultLocale: 'en',
      supportedLocales: [
        {
          id: 'en',
          preferredCurrency: 'AUD',
        },
      ],
    },
  },
  // US — single site; domestic (/us/) via SFCC, international (/en-ca/) via Global-e
  {
    id: 'ZimmermannUS',
    l10n: {
      supportedCurrencies: ['USD'],
      defaultCurrency: 'USD',
      defaultLocale: 'en-US',
      supportedLocales: [
        {
          id: 'en-US',
          alias: 'us',
          preferredCurrency: 'USD',
        },
      ],
    },
  },
  // UK — /uk/ — SFCC checkout
  {
    id: 'ZimmermannUK',
    l10n: {
      supportedCurrencies: ['GBP'],
      defaultCurrency: 'GBP',
      defaultLocale: 'en-GB',
      supportedLocales: [
        {
          id: 'en-GB',
          alias: 'uk',
          preferredCurrency: 'GBP',
        },
      ],
    },
  },
  // EU domestic — four single-locale PWA sites, all backed by SFCC ZimmermannEU
  {
    id: 'ZimmermannEUen',
    sfccSiteId: 'ZimmermannEU',
    l10n: {
      supportedCurrencies: ['EUR'],
      defaultCurrency: 'EUR',
      defaultLocale: 'en-GB',
      supportedLocales: [
        {
          id: 'en-GB',
          alias: 'en-eu',
          preferredCurrency: 'EUR',
        },
      ],
    },
  },
  {
