  if (methodTypes) {
    for (const method of Object.values(methodTypes)) {
      for (const image of method.images ?? []) {
        if (image.src?.startsWith('/icons/')) {
          image.src = `${baseUrl}${image.src}`;
        }
      }
    }
  }
  return data;
}

type SfPaymentsConfig = {
  sfPayments: { metadataUrl: string };
};

/** Express handler for GET /api/payment-metadata — fetches and transforms Adyen payment method metadata. */
export async function paymentMetadataHandler(_req: unknown, res: SsrRes): Promise<void> {
  try {
    const { app } = getConfig() as { app: SfPaymentsConfig };
    const response = await fetch(app.sfPayments.metadataUrl, {
      headers: { Accept: 'application/json' },
    });
    if (!response.ok) {
      throw new Error(`Metadata request failed with status: ${response.status}`);
    }
    const data = (await response.json()) as PaymentMethodData;
    const transformedData = transformIconPaths(data, new URL(app.sfPayments.metadataUrl).hostname);
    res.setHeader('Content-Type', 'application/json');
    res.json(transformedData);
  } catch (error) {
    res.status(500).json({
      error: 'Failed to fetch metadata',
      details: (error as Error).message,
    });
  }
}

